#include <omp.h>
#include <vector>
#include <string>
#include <cstddef>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    size_t lastIndex = n;

    #pragma omp parallel
    {
        size_t localLast = n;

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
            if (books[static_cast<size_t>(i)].pages < 100) {
                localLast = static_cast<size_t>(i);
            }
        }

        #pragma omp critical
        {
            if (localLast != n && (lastIndex == n || localLast > lastIndex)) {
                lastIndex = localLast;
            }
        }
    }

    return lastIndex;
}
